"""GeoMindAI Streamlit entry point. Run with: python -m streamlit run app.py."""
import base64
from io import BytesIO

from PIL import Image

import streamlit as st

# Embedded GeoMindAI mark: no separate asset path is required.
_FAVICON_PNG = ""
_favicon = Image.open(BytesIO(base64.b64decode(_FAVICON_PNG))).convert("RGBA")
st.set_page_config(
    page_title="GeoMindAI",
    page_icon=_favicon,
    layout="wide",
    initial_sidebar_state="expanded",
)

from geomind_ui import theme, views  # noqa: E402

theme.inject()
views.init_state()
views.startup()
views.sidebar()
page = st.session_state["page"]
if page == "settings":
    views.settings_page()
elif page == "history":
    views.history()
else:
    views.workspace()

